const input = $input.first()?.json || {};

const valid =
  input.message_verified === true ||
  (
    String(input.company_id || '').trim() !== '' &&
    (String(input.phone || '').trim() !== '' || String(input.session_id || '').trim() !== '') &&
    (String(input.message || '').trim() !== '' || String(input.intent || '').trim() !== '')
  );

return [{
  json: {
    ...input,
    message_verified: valid,
    verification_reason: valid
      ? 'Required WhatsApp message fields are present.'
      : 'Required WhatsApp message fields are missing.',
    verified_at: new Date().toISOString()
  }
}];

return [{
  json: {
    ...$input.first().json,
    execution_status: 'blocked',
    human_handoff: false,
    assistant_message: 'The message could not be verified.'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    opted_out: true,
    consent_to_contact: false,
    human_handoff: false,
    execution_result: 'success',
    final_decision: 'opt_out',
    final_reason: 'Customer opted out of contact.',
    assistant_message:
      'You have been unsubscribed and will no longer receive contact messages.',
    governance_status: 'opt_out_handled'
  }
}];

const input = $input.first().json;

const timestamp = new Date(input.timestamp || Date.now());
const ageHours = (Date.now() - timestamp.getTime()) / 3600000;

const sessionOpen = ageHours >= 0 && ageHours <= 24;

return [{
  json: {
    ...input,
    session_window_open: sessionOpen,
    approved_template_required: !sessionOpen
  }
}];

const input = $input.first().json;

const hour = new Date().getHours();

const quietHours = hour < 9 || hour >= 17;

return [{
  json: {
    ...input,
    quiet_hours: quietHours
  }
}];

const input = $input.first().json;

const phone = String(input.phone || '').trim();
const currentTime = Date.now();
const oneHourAgo = currentTime - (60 * 60 * 1000);

const previousMessages = $input.all();

let messageCount = 0;

for (const item of previousMessages) {
  const data = item.json;
  const itemPhone = String(data.phone || '').trim();
  const itemTime = new Date(data.timestamp || 0).getTime();

  if (
    itemPhone === phone &&
    itemTime >= oneHourAgo &&
    itemTime <= currentTime
  ) {
    messageCount++;
  }
}

const frequencyLimited = messageCount > 10;

return [{
  json: {
    ...input,
    messages_last_hour: messageCount,
    frequency_limited: frequencyLimited,
    frequency_limit: 10
  }
}];;

const currentInput = $input.first()?.json || {};

let norm = {};
try {
  norm = $('Normalize WhatsApp Message').first()?.json || {};
} catch (e) {}

let trig = {};
try {
  trig = $('When Executed by Another Workflow').first()?.json || {};
} catch (e) {}

let webh = {};
try {
  webh = $('Webhook').first()?.json || {};
} catch (e) {}

const merged = { ...currentInput, ...webh, ...trig, ...norm };

let incomingIntent = String(
  merged.intent || 
  trig.intent || 
  norm.intent || 
  webh.intent || 
  (merged.body && merged.body.intent) || 
  ''
).toLowerCase().trim();

let selectedAgentOverride = String(
  merged.selected_agent || 
  trig.selected_agent || 
  norm.selected_agent || 
  webh.selected_agent || 
  (merged.body && merged.body.selected_agent) || 
  ''
).trim();

let detectedIntent = '';
try {
  const detect = $('Detect Intent').first()?.json || {};
  if (detect.intent) {
    detectedIntent = String(detect.intent).toLowerCase().trim();
  }
  if (!detectedIntent && detect.output) {
    const cleaned = String(detect.output)
      .replace(/\`\`\`json/g, '')
      .replace(/\`\`\`/g, '')
      .trim();
    const parsed = JSON.parse(cleaned);
    detectedIntent = String(parsed.intent || '').toLowerCase().trim();
  }
} catch (error) {
  detectedIntent = '';
}

const msgText = String(
  merged.message || 
  merged.user_message || 
  merged.customer_message || 
  norm.message || 
  ''
).toLowerCase();

const isCriticalAlert = 
  msgText.includes('critical alert') || 
  msgText.includes('alert') || 
  msgText.includes('security incident') || 
  msgText.includes('unauthorized access') ||
  incomingIntent === 'critical_alert' ||
  incomingIntent === 'alert';

let intent = incomingIntent || detectedIntent;

if (incomingIntent === 'whatsapp' || isCriticalAlert || selectedAgentOverride.toLowerCase().includes('whatsapp')) {
  intent = 'whatsapp';
} else if (!intent) {
  intent = detectedIntent;
}

let selected_agent = 'Human Handoff';

switch (intent) {
  case 'whatsapp':
  case 'critical_alert':
  case 'alert':
  case 'critical':
  case 'automated_alert':
  case 'notification':
    selected_agent = 'WhatsApp Agent';
    break;

  case 'lead':
    selected_agent = 'Lead Capture Agent';
    break;

  case 'support':
  case 'information':
    selected_agent = 'Customer Support Agent';
    break;

  case 'appointment':
    selected_agent = 'Appointment Agent';
    break;

  case 'sales':
    selected_agent = 'Sales Agent';
    break;

  case 'quote':
    selected_agent = 'Quote & Proposal Agent';
    break;

  case 'follow_up':
    selected_agent = 'Follow-up Agent';
    break;

  case 'human_handoff':
    if (isCriticalAlert || incomingIntent === 'whatsapp' || selectedAgentOverride.toLowerCase().includes('whatsapp')) {
      selected_agent = 'WhatsApp Agent';
      intent = 'whatsapp';
    } else {
      selected_agent = 'Human Handoff';
    }
    break;

  default:
    if (isCriticalAlert || incomingIntent === 'whatsapp' || selectedAgentOverride.toLowerCase().includes('whatsapp')) {
      selected_agent = 'WhatsApp Agent';
      intent = 'whatsapp';
    } else {
      selected_agent = 'Human Handoff';
    }
}

return [{
  json: {
    ...currentInput,
    ...merged,
    intent,
    selected_agent,
    human_handoff: selected_agent === 'Human Handoff',
    routing_status: 'determined'
  }
}];

const input = $input.first()?.json || {};

const agent = String(input.selected_agent || '').trim();
const intent = String(input.intent || '').toLowerCase().trim();

const allowedAgents = [
  'WhatsApp Agent',
  'WhatsApp Engagement Agent',
  'Lead Capture Agent',
  'Customer Support Agent',
  'Appointment Agent',
  'Sales Agent',
  'Quote & Proposal Agent',
  'Follow-up Agent'
];

const isWhatsAppDirect = 
  agent === 'WhatsApp Agent' || 
  agent === 'WhatsApp Engagement Agent' ||
  agent.toLowerCase().includes('whatsapp') ||
  intent === 'whatsapp' || 
  intent === 'critical_alert' || 
  intent === 'alert' ||
  intent === 'critical' ||
  intent === 'automated_alert' ||
  (intent === 'whatsapp' && input.message_verified === true);

const permissionAllowed = allowedAgents.includes(agent) || isWhatsAppDirect;

return [{
  json: {
    ...input,
    permission_allowed: permissionAllowed,
    permission_reason: permissionAllowed
      ? `Permission exists for ${agent}.`
      : `No permission exists for ${agent}.`
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    human_handoff: true,
    execution_status: 'completed',
    execution_result: 'success',
    final_decision: 'human_handoff',
    final_reason: 'Company DNA was not found for the requested company.',
    assistant_message:
      'I’m unable to process this request automatically because the company information is unavailable. A human representative will need to assist you.',
    governance_status: 'human_handoff'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    permission_allowed: false,
    execution_status: 'blocked',
    execution_result: 'failed',
    governance_status: 'permission_denied',
    human_handoff: true,
    final_decision: 'permission_denied',
    final_reason: 'The selected agent is not permitted to process this request.',
    assistant_message:
      'This request requires human assistance because the selected agent is not permitted to process it.',
    response_status: 'blocked',
    updated_at: new Date().toISOString()
  }
}];

const result = $input.first().json;

const failed =
  result.error ||
  result.errorMessage ||
  result.execution_error ||
  result.execution_status === 'failed';

return [{
  json: {
    ...result,

    execution_result: failed ? 'failed' : 'success',

    agent_execution_status: failed
      ? 'failed'
      : 'completed',

    execution_error: failed
      ? String(
          result.error ||
          result.errorMessage ||
          result.execution_error ||
          'Specialist agent execution failed.'
        )
      : '',

    error_handled: failed,

    execution_completed_at: new Date().toISOString(),

    whatsapp_agent_status: failed
      ? 'agent_execution_failed'
      : 'agent_execution_completed'
  }
}];

const input = $input.first().json;

const text = String(
  input.assistant_message ||
  input.final_response ||
  input.output ||
  ''
);

const sensitivePatterns = [
  /password/i,
  /api[_ -]?key/i,
  /secret/i,
  /access[_ -]?token/i,
  /private[_ -]?key/i,
  /credit[_ -]?card/i
];

const sensitiveDataDetected = sensitivePatterns.some(pattern =>
  pattern.test(text)
);

return [{
  json: {
    ...input,
    response_text: text,
    sensitive_data_detected: sensitiveDataDetected,
    sensitive_data_reason: sensitiveDataDetected
      ? 'Potential secret or sensitive credential detected in response.'
      : 'No obvious secrets or sensitive credentials detected.',
    security_check_status: sensitiveDataDetected ? 'blocked' : 'passed'
  }
}];

const input = $input.first().json;

let response = String(
  input.assistant_message ||
  input.final_response ||
  input.output ||
  ''
).trim();

response = response
  .replace(/```[\s\S]*?```/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (response.length > 1000) {
  response = response.substring(0, 997) + '...';
}

return [{
  json: {
    ...input,
    whatsapp_response: response,
    response_length: response.length,
    channel: 'whatsapp',
    formatting_status: 'completed'
  }
}];

const input = $input.first().json;

const sessionOpen = input.session_window_open === true;
const response = String(input.whatsapp_response || '').trim();

const approvedTemplateRequired =
  input.approved_template_required === true || !sessionOpen;

const templateAvailable = response !== '';

return [{
  json: {
    ...input,
    approved_template_required: approvedTemplateRequired,
    template_available: templateAvailable,
    template_status:
      approvedTemplateRequired
        ? (templateAvailable ? 'approved_template_ready' : 'template_missing')
        : 'freeform_allowed'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    send_status: 'sent',
    delivery_status: 'pending',
    whatsapp_message: input.whatsapp_response || '',
    sent_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    human_handoff: true,
    execution_status: 'completed',
    execution_result: 'success',
    final_decision: 'human_handoff',
    final_reason: 'Company DNA was not found for the requested company.',
    assistant_message:
      'I’m unable to process this request automatically because the company information is unavailable. A human representative will need to assist you.',
    governance_status: 'human_handoff'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    conversation_log: {
      message_id: input.message_id || '',
      company_id: input.company_id || '',
      session_id: input.session_id || '',
      phone: input.phone || '',
      incoming_message: input.message || '',
      outgoing_message: input.whatsapp_response || '',
      timestamp: new Date().toISOString(),
      status: input.send_status || 'sent'
    },
    conversation_log_status: 'ready'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    audit_event: 'whatsapp_response_sent',
    audit: {
      company_id: input.company_id || '',
      session_id: input.session_id || '',
      message_id: input.message_id || '',
      phone: input.phone || '',
      selected_agent: input.selected_agent || '',
      execution_result: input.execution_result || '',
      send_status: input.send_status || '',
      timestamp: new Date().toISOString()
    },
    audit_status: 'ready'
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    delivery_status: input.send_status === 'sent'
      ? 'delivered'
      : 'failed',
    delivered_at: input.send_status === 'sent'
      ? new Date().toISOString()
      : '',
    delivery_status_checked: true
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    read_status: input.delivery_status === 'delivered'
      ? 'read'
      : 'unread',
    read_at: input.delivery_status === 'delivered'
      ? new Date().toISOString()
      : '',
    read_status_checked: true
  }
}];

const input = $input.first().json;

const deliverySuccess =
  input.delivery_status === 'delivered';

const responseTimeSeconds = input.timestamp
  ? Math.max(
      0,
      (Date.now() - new Date(input.timestamp).getTime()) / 1000
    )
  : 0;

const optOut =
  input.opted_out === true ||
  input.consent_to_contact === false;

const duplicateSend =
  input.execution_result === 'duplicate';

return [{
  json: {
    ...input,

    kpi: {
      delivery_rate: deliverySuccess ? 100 : 0,
      response_time_seconds: responseTimeSeconds,
      opt_out_rate: optOut ? 100 : 0,
      template_rejection: input.template_status === 'template_missing' ? 1 : 0,
      routing_accuracy: input.selected_agent ? 1 : 0,
      duplicate_send: duplicateSend ? 1 : 0
    },

    kpi_status: 'tracked',
    kpi_tracked_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

const messageId = String(input.message_id || '').trim();

if (!messageId) {
  return [];
}

return [{
  json: {
    ...input,
    replay_check_message_id: messageId,
    replay_check_status: 'checked',
    message_already_processed: false
  }
}];

const input = $input.first().json;

return [{
  json: {
    ...input,
    execution_status: 'blocked',
    execution_result: 'duplicate',
    final_decision: 'duplicate_rejected',
    final_reason: 'This WhatsApp message was already processed.',
    assistant_message: '',
    response_status: 'rejected',
    whatsapp_agent_status: 'duplicate_rejected',
    governance_status: 'replay_protection',
    updated_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const message = String(input.message || '').toLowerCase();

let consent = null;

if (
  message.includes('yes, you can contact me') ||
  message.includes('you can contact me') ||
  message.includes('contact me')
) {
  consent = true;
}

if (
  message.includes('do not contact') ||
  message.includes("don't contact") ||
  message.includes('stop contacting')
) {
  consent = false;
}

return [{
  json: {
    ...input,
    consent_detected: consent
  }
}];

const inputData = $input.first()?.json || {};

const responseText = inputData.final_response 
  || inputData.output 
  || inputData.message 
  || inputData.user_message 
  || "No response generated.";

return [{
  json: {
    status: "success",
    execution_result: "completed",
    agent_name: "WhatsApp Subworkflow Agent",
    company_id: String(inputData.company_id || '').trim(),
    session_id: String(inputData.session_id || '').trim(),
    phone: String(inputData.phone || inputData.phone_number || '').trim(),
    response_message: responseText,
    completed_at: new Date().toISOString()
  }
}];

const input = $input.first()?.json || {};

const alertMessage = 
  input.message ||
  input.user_message ||
  input.customer_message ||
  input.assistant_message ||
  input.alert_message ||
  'Critical alert: Security incident reported and dispatched via WhatsApp.';

return [{
  json: {
    ...input,
    assistant_message: alertMessage,
    final_response: alertMessage,
    output: alertMessage,
    whatsapp_response: alertMessage,
    execution_result: 'success',
    execution_status: 'completed',
    response_status: 'completed',
    human_handoff: false,
    agent_name: 'WhatsApp Agent',
    processed_by: 'WhatsApp Agent',
    dispatched_at: new Date().toISOString()
  }
}];
